/**
 * @Event 方法
 * @description: 默认创建方法：
 *      //     let map = L.map("map", {
        //         minZoom: 3,
        //         maxZoom: 18,
        //         center: [39.56, 116.20],
        //         zoom: 8,
        //         zoomControl: true, // 縮放按钮
        //         attributionControl: false, // leaflet map logo
        //         crs: L.CRS.Baidu
        //     });
 //     L.tileLayer.baidu({ layer: 'time' }).addTo(map);
 * */
require("proj4");
require("proj4leaflet");

// const titleD = 'http://127.0.0.1:8886/{z}/{x}/{y}.png'
// const titleD = 'https://api.map.baidu.com/getscript?v=3.0&ak=7pQwLpGQZr0SdQ3vlDp8gu7ExEqjKRG1'
const bdImgOnline =
  "http://online{s}.map.bdimg.com/onlinelabel/?qt=tile&x={x}&y={y}&z={z}&styles=";
// const bdImgOnline = 'http://online{s}.map.bdimg.com/onlinelabel/?qt=tile&x={x}&y={y}&z={z}&styles=' + (option.bigfont ? 'ph' : 'pl') + '&scaler=1&p=1'
const timeOnline =
  "http://its.map.baidu.com:8002/traffic/TrafficTileService?x={x}&y={y}&level={z}&time=" +
  new Date().getTime() +
  "&label=web2D&v=017";
const mapUrl =
  "http://webrd01.is.autonavi.com/appmaptile?lang=zh_cn&size=1&scale=1&style=7&x={x}&y={y}&z={z}";
const localMapUrl =
  "http://127.0.0.1:8888/api/getLeafletMap?X={x}&Y={y}&Zoom={z}&Type=788865972";
const normal =
  "http://api0.map.bdimg.com/customimage/tile?&x={x}&y={y}&z={z}&udt=20231205&scale=1&ak=5ieMMexWmzB9jivTq6oCRX9j";
const blackBg =
  "https://services.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/WMTS/tile/1.0.0/Canvas_World_Dark_Gray_Base/default/default028mm/{z}/{y}/{x}";
const landform =
  "https://services.arcgisonline.com/ArcGIS/rest/services/NatGeo_World_Map/MapServer/tile/{z}/{y}/{x}";
const landformMark =
  "https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}";
const bdImgOnlineBlue =
  " http://api0.map.bdimg.com/customimage/tile?&x={x}&y={y}&z={z}&udt=20191205&scale=1&ak=5ieMMexWmzB9jivTq6oCRX9j&customid=midnight";

L.CRS.Baidu = new L.Proj.CRS(
  "EPSG:900913",
  "+proj=merc +a=6378206 +b=6356584.314245179 +lat_ts=0.0 +lon_0=0.0 +x_0=0 +y_0=0 +k=1.0 +units=m +nadgrids=@null +wktext  +no_defs",
  {
    resolutions: (function () {
      level = 19;
      var res = [];
      res[0] = Math.pow(2, 18);
      for (var i = 1; i <= level; i++) {
        res[i] = Math.pow(2, 18 - i);
      }
      return res;
    })(),
    origin: [0, 0],
    bounds: L.bounds([20037508.342789244, 0], [0, 20037508.342789244]),
  }
);

L.tileLayer.baidu = function (option) {
  option = option || {};
  var layer;
  var subdomains = "0123456789";
  switch (option.layer) {
    // 单图层
    case "vec":
    default:
      layer = L.tileLayer(bdImgOnline, {
        name: option.name,
        subdomains: subdomains,
        tms: true,
        maxZoom: 19,
        minZoom: 4,
        maxNativeZoom: 19,
        attribution:
          '&copy; <a href="http://osm.org/copyright">OpenStreetMap</a> contributors',
      });
      break;

    //卫星图
    case "img_d":
      layer = L.tileLayer(
        "http://shangetu{s}.map.bdimg.com/it/u=x={x};y={y};z={z};v=009;type=sate&fm=46",
        {
          name: option.name,
          subdomains: subdomains,
          tms: true,
        }
      );
      break;

    // 卫星图 实时路况
    case "img_z":
      layer = L.tileLayer(
        "http://online{s}.map.bdimg.com/tile/?qt=tile&x={x}&y={y}&z={z}&styles=" +
          (option.bigfont ? "sh" : "sl") +
          "&v=020",
        {
          name: option.name,
          subdomains: subdomains,
          tms: true,
        }
      );
      break;

    //custom 各种自定义样式
    case "custom":
      //可选值：dark,midnight,grayscale,hardedge,light,redalert,googlelite,grassgreen,pink,darkgreen,bluish
      option.customid = option.customid || "midnight";
      layer = L.tileLayer(
        "http://api{s}.map.bdimg.com/customimage/tile?&x={x}&y={y}&z={z}&scale=1&customid=" +
          option.customid,
        {
          name: option.name,
          subdomains: "012",
          tms: true,
        }
      );
      // layer = L.tileLayer(bdImgOnline, {
      //     name: option.name, subdomains: subdomains, tms: true
      // });
      break;

    //实时路况
    case "time":
      layer = L.tileLayer(timeOnline, {
        name: option.name,
        subdomains: subdomains,
        tms: true,
      });
      break;

    // 卫星图 + 卫星图 实时路况 合并 demo
    case "img":
      layer = L.layerGroup([
        L.tileLayer.baidu({
          name: "底图",
          layer: "img_d",
          bigfont: option.bigfont,
        }),
        L.tileLayer.baidu({
          name: "注记",
          layer: "img_z",
          bigfont: option.bigfont,
        }),
      ]);
      break;

    // 单图层 + 单图层 实时路况 合并 demo
    case "img2":
      layer = L.layerGroup([
        L.tileLayer.baidu({
          name: "底图",
          layer: "vec",
          bigfont: option.bigfont,
        }),
        L.tileLayer.baidu({
          name: "注记",
          layer: "time",
          bigfont: option.bigfont,
        }),
      ]);
      break;

    // 正常百度地图
    case "img3":
      layer = L.tileLayer(normal, {
        tms: true,
        maxZoom: 19,
        minZoom: 4,
      });
      break;

    // 暗黑地图URL
    case "img5":
      layer = L.tileLayer(blackBg, {
        tms: true,
        maxZoom: 19,
        minZoom: 4,
      });
      break;

    // 地形图
    case "img6":
      layer = L.tileLayer(landform, {
        tms: true,
        maxZoom: 19,
        minZoom: 4,
      });
      break;

    // 地形+标注图2URL
    case "img7":
      layer = L.tileLayer(landformMark, {
        tms: true,
        maxZoom: 19,
        minZoom: 4,
      });
      break;

    // 夜深色地图，蓝色地图
    case "img8":
      layer = L.tileLayer(bdImgOnlineBlue, {
        name: option.name,
        subdomains: subdomains,
        tms: true,
        maxZoom: 19,
        minZoom: 4,
        maxNativeZoom: 19,
        attribution:
          '&copy; <a href="http://osm.org/copyright">OpenStreetMap</a> contributors',
      });
      break;

    // 离线百度地图
    case "localMap":
      layer = L.tileLayer(localMapUrl, {
        name: option.name,
        subdomains: subdomains,
        tms: true,
      });
      break;
  }
  return layer;
};
